public Frame addFrame() {
    Frame frameClone;
    Frame frame;
    boolean z = !this.mFrames.isEmpty() && isEnd();
    int framesNumber = getFramesNumber();
    int currentIndex = getCurrentIndex() + 1;
    if (this.mFrames.isEmpty()) {
        frame = new Frame(this, 0);
        this.mFrames.add(frame);
    } else {
        if (isEnd()) {
            frameClone = currentFrame().clone();
            frameClone.setId(generateFrameId());
            this.mFrames.add(getCurrentIndex() + 1, frameClone);
        } else {
            frameClone = InterpolatorFactory.forInterpolation().interpolate(currentFrame(), this.mFrames.get(getCurrentIndex() + 1), 2, this).get(1);
            frameClone.setId(generateFrameId());
            frameClone.updateUnits();
            frameClone.onStructureChanged();
            this.mFrames.add(getCurrentIndex() + 1, frameClone);
        }
        frame = frameClone;
    }
    updateSpeedPoints();
    if (!z && framesNumber > 0) {
        this.mTweens.reconcileCameraForInsert(this, framesNumber, currentIndex, "add-frame");
    }
    selectedRange().clear();
    showNext();
    return frame;
}
